const { Schema } = mongoose

const ASchema = new Schema(
  {
    b_ids: [{ type: Schema.Types.ObjectId, ref: "B" }],
  },
  { timestamps: false },
)
const A = mongoose.model("A", ASchema, "a")

const BSchema = new Schema(
  {
    x: { type: Number },
  },
  { timestamps: false },
)
const B = mongoose.model("B", BSchema, "b")

module.exports = { A, B }

